-- Wikipedia movie dataset for Postgres full-text search practice
-- Load with: psql -d yourdb -f movies.sql

BEGIN;

DROP TABLE IF EXISTS movies;

CREATE TABLE movies (
    id          int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title       text NOT NULL,
    year        int,
    cast_members text[],
    genres      text[],
    plot        text NOT NULL
);


COMMIT;

ANALYZE movies;
